<?php
declare(strict_types=1);require __DIR__.'/_init.php';try{$resource=(string)($_GET['resource']??'');$allowed=['suppliers'=>'suppliers','warehouses'=>'warehouses','batches'=>'batches','items'=>'items','movements'=>'stock_movements'];if(!isset($allowed[$resource]))json_response(false,null,'NOT_FOUND','Unknown resource.',[],404);if($_SERVER['REQUEST_METHOD']==='GET'){$table=$allowed[$resource];$sql=match($resource){'batches'=>'SELECT b.*,i.name item_name,i.sku,s.name supplier_name FROM batches b JOIN items i ON i.id=b.item_id LEFT JOIN suppliers s ON s.id=b.supplier_id ORDER BY b.id DESC LIMIT 500','suppliers'=>'SELECT id,name,contact_person,email,phone,address,lead_time_days,payment_terms,is_active FROM suppliers ORDER BY name','warehouses'=>'SELECT id,name,code,address,is_active FROM warehouses ORDER BY name','items'=>'SELECT id,sku,name,unit,reorder_level,reorder_qty,unit_cost,preferred_supplier_id,is_active FROM items ORDER BY name','movements'=>'SELECT * FROM stock_movements ORDER BY id DESC LIMIT 500',default=>"SELECT * FROM `$table` ORDER BY id DESC LIMIT 500"};json_response(true,$pdo->query($sql)->fetchAll());} $d=request_json();if($resource==='suppliers'){$pdo->prepare('INSERT INTO suppliers(name,contact_person,email,phone,address,lead_time_days,payment_terms,notes) VALUES(?,?,?,?,?,?,?,?)')->execute([trim((string)($d['name']??'')),trim((string)($d['contact_person']??''))?:null,trim((string)($d['email']??''))?:null,trim((string)($d['phone']??''))?:null,trim((string)($d['address']??''))?:null,max(0,(int)($d['lead_time_days']??7)),trim((string)($d['payment_terms']??''))?:null,trim((string)($d['notes']??''))?:null]);}elseif($resource==='warehouses'){$pdo->prepare('INSERT INTO warehouses(name,code,address) VALUES(?,?,?)')->execute([trim((string)($d['name']??'')),trim((string)($d['code']??'')),trim((string)($d['address']??''))?:null]);}elseif($resource==='items'){$sku=trim((string)($d['sku']??''));$name=trim((string)($d['name']??''));if($sku===''||$name==='')json_response(false,null,'VALIDATION_ERROR','SKU and product name are required.',[],422);$sup=isset($d['preferred_supplier_id'])&&$d['preferred_supplier_id']!==''?(int)$d['preferred_supplier_id']:null;$pdo->prepare('INSERT INTO items(sku,name,unit,reorder_level,reorder_qty,unit_cost,preferred_supplier_id) VALUES(?,?,?,?,?,?,?)')->execute([$sku,$name,trim((string)($d['unit']??'pcs')),(int)($d['reorder_level']??0),(int)($d['reorder_qty']??0),(float)($d['unit_cost']??0),$sup]);}elseif($resource==='batches'){$item=positive_int($d['item_id']??null,'item_id');$number=trim((string)($d['batch_number']??''));$manufactured=(string)($d['manufacturing_date']??'');$expires=(string)($d['expiration_date']??'');if($number===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$manufactured)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$expires)||$expires<=$manufactured)json_response(false,null,'VALIDATION_ERROR','Enter a batch number and valid manufacturing/expiration dates.',[],422);$supplier=isset($d['supplier_id'])&&$d['supplier_id']!==''?(int)$d['supplier_id']:null;$qty=max(0,(int)($d['initial_quantity']??0));$warehouse=isset($d['warehouse_id'])&&$d['warehouse_id']!==''?(int)$d['warehouse_id']:null;if($qty>0&&!$warehouse)json_response(false,null,'VALIDATION_ERROR','Choose a warehouse when opening quantity is greater than zero.',[],422);$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO batches(item_id,batch_number,manufacturing_date,expiration_date,received_date,supplier_id,unit_cost) VALUES(?,?,?,?,CURDATE(),?,?)')->execute([$item,$number,$manufactured,$expires,$supplier,(float)($d['unit_cost']??0)]);$batchId=(int)$pdo->lastInsertId();if($qty>0)InventoryService::move($pdo,$batchId,$warehouse,$qty,'receive','Opening stock for batch '.$number,(int)$user['id']);$pdo->commit();json_response(true,['id'=>$batchId],null,'Batch registered.',[],201);}catch(Throwable $e){$pdo->rollBack();throw $e;}}else json_response(false,null,'NOT_IMPLEMENTED','This resource cannot be created here.',[],422);json_response(true,['id'=>(int)$pdo->lastInsertId()],null,'Record created.',[],201);}catch(PDOException $e){if((string)$e->getCode()==='23000')json_response(false,null,'CONFLICT','A record with this unique value already exists or a related record is invalid.',[],409);api_error($e);}catch(Throwable $e){api_error($e);}
